let miniDragState={active:false,moved:false,x:0,y:0,startX:0,startY:0};
function initMiniDrag(){miniPlayer.addEventListener("mousedown",startMiniDrag);miniPlayer.addEventListener("touchstart",startMiniDrag,{passive:false});}
function startMiniDrag(e){
  miniDragState.active=true;miniDragState.moved=false;
  const ev=e.touches?e.touches[0]:e;
  const rect=miniPlayer.getBoundingClientRect();
  miniDragState.x=rect.left;miniDragState.y=rect.top;
  miniDragState.startX=ev.clientX-miniDragState.x;miniDragState.startY=ev.clientY-miniDragState.y;
  miniPlayer.style.transition="none";
  document.addEventListener("mousemove",moveMiniDrag);
  document.addEventListener("mouseup",endMiniDrag);
  document.addEventListener("touchmove",moveMiniDrag,{passive:false});
  document.addEventListener("touchend",endMiniDrag);
}
function moveMiniDrag(e){
  if(!miniDragState.active)return;
  e.preventDefault();miniDragState.moved=true;
  const ev=e.touches?e.touches[0]:e;
  const nx=ev.clientX-miniDragState.startX,ny=ev.clientY-miniDragState.startY;
  const maxX=window.innerWidth-miniPlayer.offsetWidth,maxY=window.innerHeight-miniPlayer.offsetHeight;
  miniDragState.x=Math.max(0,Math.min(maxX,nx));miniDragState.y=Math.max(0,Math.min(maxY,ny));
  miniPlayer.style.left=miniDragState.x+"px";miniPlayer.style.top=miniDragState.y+"px";
  miniPlayer.style.right="auto";miniPlayer.style.bottom="auto";
}
function endMiniDrag(){
  miniDragState.active=false;miniPlayer.style.transition="";
  document.removeEventListener("mousemove",moveMiniDrag);
  document.removeEventListener("mouseup",endMiniDrag);
  document.removeEventListener("touchmove",moveMiniDrag);
  document.removeEventListener("touchend",endMiniDrag);
  if(!miniDragState.moved)__id("miniToggle").click();
}
