    const f=file.files&&file.files[0];file.value="";
    if(!f)return;
    if(!/\\.tvcbak$/i.test(f.name)&&f.name.indexOf("tvbox-backup")!==0){toast("\u8BF7\u9009\u62E9 .tvcbak \u5907\u4EFD\u6587\u4EF6");return;}
    const pwd=await bkAskKey("import");
